import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find all conditional statements in the unit block
    walk(parent, [_, node])
    node.ir_type == "ConditionalStatement"
    node.type == "SWITCH"

    # Check if there's no default case
    not has_default_case(node)

    result := {
        "type": "sec_no_default_switch",
        "element": node,
        "path": parent.path,
        "description": "Missing default case in multiple condition expression - Switch statements should have a default case to handle unexpected values. (CWE-478)"
    }
}

# Helper to check if a conditional statement has a default case
has_default_case(node) {
    node.is_default == true
} else {
    node.else_statement != null
    has_default_case(node.else_statement)
} else {
    # Check in statements of the block for nested conditionals that might be default
    some stmt in node.statements
    stmt.ir_type == "ConditionalStatement"
    stmt.is_default == true
} else {
    # Walk through any nested structures to find default case
    walk(node, [_, child])
    child.ir_type == "ConditionalStatement"
    child.is_default == true
}

